        [new Guid("00062040-0000-0000-C000-000000000046")] = "PSETID_Sharing",
        [new Guid("00062003-0000-0000-C000-000000000046")] = "PSETID_Task",
        [new Guid("4442858E-A9E3-4E80-B900-317A210CC15B")] = "PSETID_UnifiedMessaging",
        [new Guid("23239608-685D-4732-9C55-4C95CB4E8E33")] = "PSETID_XmlExtractedEntities",
        };

    public static string? PidTag(ushort propertyId) =>
        PidTags.GetValueOrDefault(propertyId);

    public static string? PidLid(string propertySet, ushort propertyId) =>
        PidLids.GetValueOrDefault($"{propertySet}:{propertyId:X4}");

    public static string? PidName(string propertySet, string propertyName) =>
        PidNames.GetValueOrDefault($"{propertySet}::{propertyName}");

    public static string? PropertySetName(Guid propertySet) =>
        PropertySetNames.GetValueOrDefault(propertySet);

    public static string FormatPidTag(ushort propertyId)
    {
        var name = PidTag(propertyId);
        return name is null ? $"0x{propertyId:X4}" : $"0x{propertyId:X4} {name}";
    }
}
